#include <bits/stdc++.h>
using namespace std;

long double my_abs(long double val) {
    return val < 0 ? -val : val;
}

int main() {
    int a, b, n;
    cin >> a >> b >> n;
    int x, y_upper, y_lower;
    long double min_diff = 1e100;
    int res_x = 0, res_y = 0;
    for (int i = 1; i <= n; ++i) {
        x = i;
        y_upper = static_cast<int>((long double)a / b * i);
        y_lower = y_upper + 1;
        long double diff_upper = my_abs((long double)a / b - (long double)y_upper / x);
        long double diff_lower = my_abs((long double)a / b - (long double)y_lower / x);
        if (min_diff > diff_upper) {
            min_diff = diff_upper;
            res_x = y_upper;
            res_y = x;
        }
        if (min_diff > diff_lower) {
            min_diff = diff_lower;
            res_x = y_lower;
            res_y = x;
        }
    }
    cout << res_x << "/" << res_y << endl;
}
